WITH expected AS (SELECT * FROM JSON_TABLE(_utf8mb4 X'', '$[*]' COLUMNS(`TABLE_NAME` VARCHAR(2048) PATH '$[0]' NULL ON EMPTY NULL ON ERROR,`COLUMN_NAME` VARCHAR(2048) PATH '$[1]' NULL ON EMPTY NULL ON ERROR,`ORDINAL_POSITION` BIGINT PATH '$[2]' NULL ON EMPTY NULL ON ERROR,`COLUMN_TYPE` VARCHAR(2048) PATH '$[3]' NULL ON EMPTY NULL ON ERROR,`DATA_TYPE` VARCHAR(2048) PATH '$[4]' NULL ON EMPTY NULL ON ERROR,`IS_NULLABLE` VARCHAR(2048) PATH '$[5]' NULL ON EMPTY NULL ON ERROR,`COLUMN_KEY` VARCHAR(2048) PATH '$[6]' NULL ON EMPTY NULL ON ERROR,`EXTRA` VARCHAR(2048) PATH '$[7]' NULL ON EMPTY NULL ON ERROR,`COLUMN_DEFAULT` VARCHAR(2048) PATH '$[8]' NULL ON EMPTY NULL ON ERROR,`CHARACTER_SET_NAME` VARCHAR(2048) PATH '$[9]' NULL ON EMPTY NULL ON ERROR,`COLLATION_NAME` VARCHAR(2048) PATH '$[10]' NULL ON EMPTY NULL ON ERROR,`GENERATION_EXPRESSION` VARCHAR(2048) PATH '$[11]' NULL ON EMPTY NULL ON ERROR,`SRS_ID` BIGINT PATH '$[12]' NULL ON EMPTY NULL ON ERROR,`COLUMN_COMMENT` VARCHAR(2048) PATH '$[13]' NULL ON EMPTY NULL ON ERROR)) AS j), actual AS (SELECT DISTINCT `TABLE_NAME`,`COLUMN_NAME`,`ORDINAL_POSITION`,REPLACE(`COLUMN_TYPE`,'utf8mb3','utf8') AS `COLUMN_TYPE`,REPLACE(`DATA_TYPE`,'utf8mb3','utf8') AS `DATA_TYPE`,`IS_NULLABLE`,`COLUMN_KEY`,`EXTRA`,`COLUMN_DEFAULT`,REPLACE(`CHARACTER_SET_NAME`,'utf8mb3','utf8') AS `CHARACTER_SET_NAME`,REPLACE(`COLLATION_NAME`,'utf8mb3','utf8') AS `COLLATION_NAME`,`GENERATION_EXPRESSION`,`SRS_ID`,`COLUMN_COMMENT` FROM information_schema.COLUMNS s WHERE `TABLE_SCHEMA`=DATABASE() AND TABLE_NAME IN (_utf8mb4 X'74656c656772616d5f626f745f73657474696e6773',_utf8mb4 X'746573745f73657373696f6e73',_utf8mb4 X'74657374735f6f7574',_utf8mb4 X'757365725f696d706f72745f6a6f625f726573756c7473',_utf8mb4 X'757365725f696d706f72745f6a6f6273',_utf8mb4 X'757365725f696d706f72745f73657373696f6e73',_utf8mb4 X'7a61705f6461746573')) SELECT 'columns_missing_or_changed' AS check_name, COUNT(*) AS mismatch_count FROM expected e LEFT JOIN actual a ON BINARY a.`TABLE_NAME` <=> BINARY e.`TABLE_NAME` AND BINARY a.`COLUMN_NAME` <=> BINARY e.`COLUMN_NAME` AND a.`ORDINAL_POSITION` <=> e.`ORDINAL_POSITION` AND BINARY a.`COLUMN_TYPE` <=> BINARY e.`COLUMN_TYPE` AND BINARY a.`DATA_TYPE` <=> BINARY e.`DATA_TYPE` AND BINARY a.`IS_NULLABLE` <=> BINARY e.`IS_NULLABLE` AND BINARY a.`COLUMN_KEY` <=> BINARY e.`COLUMN_KEY` AND BINARY a.`EXTRA` <=> BINARY e.`EXTRA` AND BINARY a.`COLUMN_DEFAULT` <=> BINARY e.`COLUMN_DEFAULT` AND BINARY a.`CHARACTER_SET_NAME` <=> BINARY e.`CHARACTER_SET_NAME` AND BINARY a.`COLLATION_NAME` <=> BINARY e.`COLLATION_NAME` AND BINARY a.`GENERATION_EXPRESSION` <=> BINARY e.`GENERATION_EXPRESSION` AND a.`SRS_ID` <=> e.`SRS_ID` AND BINARY a.`COLUMN_COMMENT` <=> BINARY e.`COLUMN_COMMENT` WHERE a.`TABLE_NAME` IS NULL UNION ALL SELECT 'columns_unexpected_or_changed',COUNT(*) FROM actual a LEFT JOIN expected e ON BINARY a.`TABLE_NAME` <=> BINARY e.`TABLE_NAME` AND BINARY a.`COLUMN_NAME` <=> BINARY e.`COLUMN_NAME` AND a.`ORDINAL_POSITION` <=> e.`ORDINAL_POSITION` AND BINARY a.`COLUMN_TYPE` <=> BINARY e.`COLUMN_TYPE` AND BINARY a.`DATA_TYPE` <=> BINARY e.`DATA_TYPE` AND BINARY a.`IS_NULLABLE` <=> BINARY e.`IS_NULLABLE` AND BINARY a.`COLUMN_KEY` <=> BINARY e.`COLUMN_KEY` AND BINARY a.`EXTRA` <=> BINARY e.`EXTRA` AND BINARY a.`COLUMN_DEFAULT` <=> BINARY e.`COLUMN_DEFAULT` AND BINARY a.`CHARACTER_SET_NAME` <=> BINARY e.`CHARACTER_SET_NAME` AND BINARY a.`COLLATION_NAME` <=> BINARY e.`COLLATION_NAME` AND BINARY a.`GENERATION_EXPRESSION` <=> BINARY e.`GENERATION_EXPRESSION` AND a.`SRS_ID` <=> e.`SRS_ID` AND BINARY a.`COLUMN_COMMENT` <=> BINARY e.`COLUMN_COMMENT` WHERE e.`TABLE_NAME` IS NULL$$

