RY e.`IS_NULLABLE` AND BINARY a.`COLUMN_KEY` <=> BINARY e.`COLUMN_KEY` AND BINARY a.`EXTRA` <=> BINARY e.`EXTRA` AND BINARY a.`COLUMN_DEFAULT` <=> BINARY e.`COLUMN_DEFAULT` AND BINARY a.`CHARACTER_SET_NAME` <=> BINARY e.`CHARACTER_SET_NAME` AND BINARY a.`COLLATION_NAME` <=> BINARY e.`COLLATION_NAME` AND BINARY a.`GENERATION_EXPRESSION` <=> BINARY e.`GENERATION_EXPRESSION` AND a.`SRS_ID` <=> e.`SRS_ID` AND BINARY a.`COLUMN_COMMENT` <=> BINARY e.`COLUMN_COMMENT` WHERE a.`TABLE_NAME` IS NULL UNION ALL SELECT 'columns_unexpected_or_changed',COUNT(*) FROM actual a LEFT JOIN expected e ON BINARY a.`TABLE_NAME` <=> BINARY e.`TABLE_NAME` AND BINARY a.`COLUMN_NAME` <=> BINARY e.`COLUMN_NAME` AND a.`ORDINAL_POSITION` <=> e.`ORDINAL_POSITION` AND BINARY a.`COLUMN_TYPE` <=> BINARY e.`COLUMN_TYPE` AND BINARY a.`DATA_TYPE` <=> BINARY e.`DATA_TYPE` AND BINARY a.`IS_NULLABLE` <=> BINARY e.`IS_NULLABLE` AND BINARY a.`COLUMN_KEY` <=> BINARY e.`COLUMN_KEY` AND BINARY a.`EXTRA` <=> BINARY e.`EXTRA` AND BINARY a.`COLUMN_DEFAULT` <=> BINARY e.`COLUMN_DEFAULT` AND BINARY a.`CHARACTER_SET_NAME` <=> BINARY e.`CHARACTER_SET_NAME` AND BINARY a.`COLLATION_NAME` <=> BINARY e.`COLLATION_NAME` AND BINARY a.`GENERATION_EXPRESSION` <=> BINARY e.`GENERATION_EXPRESSION` AND a.`SRS_ID` <=> e.`SRS_ID` AND BINARY a.`COLUMN_COMMENT` <=> BINARY e.`COLUMN_COMMENT` WHERE e.`TABLE_NAME` IS NULL$$

WITH expected AS (SELECT * FROM JSON_TABLE(_utf8mb4 X'', '$[*]' COLUMNS(`TABLE_NAME` VARCHAR(2048) PATH '$[0]' NULL ON EMPTY NULL ON ERROR,`CONSTRAINT_NAME` VARCHAR(2048) PATH '$[1]' NULL ON EMPTY NULL ON ERROR,`COLUMN_NAME` VARCHAR(2048) PATH '$[2]' NULL ON EMPTY NULL ON ERROR,`ORDINAL_POSITION` BIGINT PATH '$[3]' NULL ON EMPTY NULL ON ERROR,`REFERENCED_TABLE_NAME` VARCHAR(2048) PATH '$[4]' NULL ON EMPTY NULL ON ERROR,`REFERENCED_COLUMN_NAME` VARCHAR(2048) PATH '$[5]' NULL ON EMPTY NULL ON ERROR,`UPDATE_RULE` VARCHAR(2048) PATH '$[6]' NULL ON EMPTY NULL ON ERROR,`DELETE_RULE` VARCHAR(2048) PATH '$[7]' NULL ON EMPTY NULL ON ERROR)) AS j), actual AS (SELECT DISTINCT `TABLE_NAME`,`CONSTRAINT_NAME`,`COLUMN_NAME`,`ORDINAL_POSITION`,`REFERENCED_TABLE_NAME`,`REFERENCED_COLUMN_NAME`,`UPDATE_RULE`,`DELETE_RULE` FROM (SELECT k.TABLE_SCHEMA,k.TABLE_NAME,k.CONSTRAINT_NAME,k.COLUMN_NAME,k.ORDINAL_POSITION,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,r.UPDATE_RULE,r.DELETE_RULE FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.REFERENCED_TABLE_NAME IS NOT NULL) s WHERE `TABLE_SCHEMA`=DATABASE()) SELECT 'foreign_keys_missing_or_changed' AS check_name, COUNT(*) AS mismatch_count FROM expected e LEFT JOIN actual a ON BINARY a.`TABLE_NAME` <=> BINARY e.`TABLE_NAME` AND BINARY a.`CONSTRAINT_NAME` <=> BINARY e.`CONSTRAINT_NAME` AND BINARY a.`COLUMN_NAME` <=> BINARY e.`COLUMN_NAME` AND a.`ORDINAL_POSITION` <=> e.`ORDINAL_POSITION` AND BINARY a.`REFERENCED_TABLE_NAME` <=> BINARY e.`REFERENCED_TABLE_NAME` AND BINARY a.`REFERENCED_COLUMN_NAME` <=> BINARY e.`REFERENCED_COLUMN_NAME` AND BINARY a.`UPDATE_RULE` <=> BINARY e.`UPDATE_RULE` AND BINARY a.`DELETE_RULE` <=> BINARY e.`DELETE_RULE` WHERE a.`TABLE_NAME` IS NULL UNION ALL SELECT 'foreign_keys_unexpected_or_changed',COUNT(*) FROM actual a LEFT JOIN expected e ON BINARY a.`TABLE_NAME` <=> BINARY e.`TABLE_NAME` AND BINARY a.`CONSTRAINT_NAME` <=> BINARY e.`CONSTRAINT_NAME` AND BINARY a.`COLUMN_NAME` <=> BINARY e.`COLUMN_NAME` AND a.`ORDINAL_POSITION` <=> e.`ORDINAL_POSITION` AND BINARY a.`REFERENCED_TABLE_NAME` <=> BINARY e.`REFERENCED_TABLE_NAME` AND BINARY a.`REFERENCED_COLUMN_NAME` <=> BINARY e.`REFERENCED_COLUMN_NAME` AND BINARY a.`UPDATE_RULE` <=> BINARY e.`UPDATE_RULE` AND BINARY a.`DELETE_RULE` <=> BINARY e.`DELETE_RULE` WHERE e.`TABLE_NAME` IS NULL$$

WITH expected AS (SELECT * FROM JSON_TABLE(_utf8mb4 X'', '$[*]' COLUMNS(`TABLE_NAME` VARCHAR(2048) PATH '$[0]' NULL ON EMPTY NULL ON ERROR,`INDEX_NAME` VARCHAR(2048) PATH '$[1]' NULL ON EMPTY NULL ON ERROR,`NON_UNIQUE` BIGINT PATH '$[2]' NULL ON EMPTY NULL ON ERROR,`SEQ_IN_INDEX` BIGINT PATH '$[3]' NULL ON EMPTY NULL ON ERROR,`COLUMN_NAME` VARCHAR(2048) PATH '$[4]' NULL ON EMPTY NULL ON ERROR,`SUB_PART` BIGINT PATH '$[5]' NULL ON EMPTY NULL ON ERROR,`INDEX_TYPE` VARCHAR(2048) PATH '$[6]' NULL ON EMPTY NULL ON ERROR,`IS_VISIBLE` VARCHAR(2048) PATH '$[7]' NULL ON EMPTY NULL ON ERROR,`EXPRESSION` VARCHAR(2048) PATH '$[8]' NULL ON EMPTY NULL ON ERROR)) AS j), actual AS (SELECT DISTINCT `TABLE_NAME`,`INDEX_NAME`,`NON_UNIQUE`,`SEQ_IN_INDEX`,`COLUMN_NAME`,`SUB_PART`,`INDEX_TYPE`,`IS_VISIBLE`,`EXPRESSION` FROM information_schema.STATISTICS s WHERE `TABLE_SCHEMA`=DATABASE() AND TABLE_NAME IN (_utf8mb4 X'416c6c726174696e6773',_utf8mb4 X'61646d696e5f726f6c655f7065726d697373696f6e73',_utf8mb4 X'61646d696e5f726f6c655f7573657273',_utf8mb4 X'61646d696e5f726f6c6573',_utf8mb4 X'61646d696e73',_utf8mb4 X'6170706c69636174696f6e5f73657474696e6773',_utf8mb4 X'617474656e64616e6365',_utf8mb4 X'617474656e64616e63655f7479706573',_utf8mb4 X'617574685f7573657273',_utf8mb4 X'636172645f7468656d6573',_utf8mb4 X'6361726473',_utf8mb4 X'636c6173735f6461795f617474656e64616e6365',_utf8mb4 X'636c6173735f64617973',_utf8mb4 X'636c61737369635f6578616d5f61707065616c73',_utf8mb4 X'636c61737369635f6578616d5f61737369676e6d656e745f696d706f72745f73657373696f6e73',_utf8mb4 X'636c61737369635f6578616d5f61737369676e6d656e745f6d656d62657273',_utf8mb4 X'636c61737369635f6578616d5f61737369676e6d656e7473',_utf8mb4 X'636c61737369635f6578616d5f617474656d70745f636f6d6d616e6473',_utf8mb4 X'636c61737369635f6578616d5f617474656d70745f6d656d62657273',_utf8mb4 X'636c61737369635f6578616d5f617474656d70745f706172745f70726f6772657373',_utf8mb4 X'636c61737369635f6578616d5f617474656d70745f7175657374696f6e5f7573616765',_utf8mb4 X'636c6